class MockBreakpointObserver {
  observe() {
    return of({
      matches: false,
      breakpoints: {
        [Breakpoints.XLarge]: false,
        [Breakpoints.Large]: false,
        [Breakpoints.Medium]: false,
        [Breakpoints.Small]: false,
        [Breakpoints.XSmall]: false,
      },
    });
  }
}

class MobileBreakpointObserver {
  observe() {
    return of({ matches: true, breakpoints: { [Breakpoints.XSmall]: true } });
  }
}

const transloco = TranslocoTestingModule.forRoot({
  langs: {
    en: {
      common: {
        empty: 'Nothing here',
        loadError: 'Load failed',
        retry: 'Retry',
        list: { columns: 'Columns', selectAll: 'Select all', selectRow: 'Select row' },
      },
    },
  },
  translocoConfig: { availableLangs: ['en'], defaultLang: 'en' },
});

